func TestVectorsWAL(t *testing.T) {
	v := loadVectors(t)
	f := newFixture(t)
	msgs := f.p2pMessages(t)

	walVote := &cmtcons.TimedWALMessage{
		Time: fixedTime,
		Msg:  &cmtcons.WALMessage{Sum: &cmtcons.WALMessage_MsgInfo{MsgInfo: &cmtcons.MsgInfo{Msg: *msgs["p2p_vote"], PeerID: ""}}},
	}
	v.eqHex(t, "wal_msginfo_vote_proto", mustMarshal(t, walVote))
	walTimeout := &cmtcons.TimedWALMessage{
		Time: fixedTime,
		Msg: &cmtcons.WALMessage{Sum: &cmtcons.WALMessage_TimeoutInfo{TimeoutInfo: &cmtcons.TimeoutInfo{
			Duration: 3 * time.Second, Height: height, Round: round, Step: 4,
		}}},
	}
	v.eqHex(t, "wal_timeout_proto", mustMarshal(t, walTimeout))
	walEnd := &cmtcons.TimedWALMessage{
		Time: fixedTime,
		Msg:  &cmtcons.WALMessage{Sum: &cmtcons.WALMessage_EndHeight{EndHeight: &cmtcons.EndHeight{Height: height}}},
	}
	v.eqHex(t, "wal_end_height_proto", mustMarshal(t, walEnd))
	walRS := &cmtcons.TimedWALMessage{
		Time: fixedTime,
		Msg: &cmtcons.WALMessage{Sum: &cmtcons.WALMessage_EventDataRoundState{EventDataRoundState: &cmtproto.EventDataRoundState{
			Height: height, Round: round, Step: "RoundStepPropose",
		}}},
	}
	v.eqHex(t, "wal_event_round_state_proto", mustMarshal(t, walRS))

	// MsgInfo.receive_time (field 3) is persisted exactly as on bera-v1.x, so
	// a proposal replayed from a WAL written by either line keeps its PBTS
	// timeliness verdict.
	rt := fixedTimeNext
	walProposalRT := &cmtcons.TimedWALMessage{
		Time: fixedTime,
		Msg: &cmtcons.WALMessage{Sum: &cmtcons.WALMessage_MsgInfo{MsgInfo: &cmtcons.MsgInfo{
			Msg: *msgs["p2p_proposal"], PeerID: "peer1", ReceiveTime: &rt,
		}}},
	}
	v.eqHex(t, "wal_msginfo_proposal_with_receive_time_proto", mustMarshal(t, walProposalRT))
	withRT := new(cmtcons.TimedWALMessage)
	require.NoError(t, withRT.Unmarshal(v.hex(t, "wal_msginfo_proposal_with_receive_time_proto")))
	mi, ok := withRT.Msg.Sum.(*cmtcons.WALMessage_MsgInfo)
	require.True(t, ok)
	assert.Equal(t, "peer1", mi.MsgInfo.PeerID)
	require.NotNil(t, mi.MsgInfo.ReceiveTime)
	assert.True(t, fixedTimeNext.Equal(*mi.MsgInfo.ReceiveTime))
	assert.True(t, fixedTime.Equal(withRT.Time))
	v.eqHex(t, "p2p_proposal", mustMarshal(t, &mi.MsgInfo.Msg))
}

func TestVectorsGenesisAndPrivval(t *testing.T) {
	v := loadVectors(t)
	f := newFixture(t)

	// genesis.json written by bera-v1.x
	genDoc, err := types.GenesisDocFromJSON([]byte(v.str(t, "genesis_json")))
	require.NoError(t, err)
	require.NoError(t, genDoc.ValidateAndComplete())
	assert.Equal(t, chainID, genDoc.ChainID)
	assert.True(t, fixedTime.Equal(genDoc.GenesisTime))
	assert.EqualValues(t, 1, genDoc.InitialHeight)
	assert.Equal(t, h32("genesis-app"), []byte(genDoc.AppHash))
	assert.JSONEq(t, `{"k":"v"}`, string(genDoc.AppState))
	require.NotNil(t, genDoc.ConsensusParams)
	assert.Equal(t, f.params, *genDoc.ConsensusParams)
	v.eqHex(t, "params_hash", genDoc.ConsensusParams.Hash())
	v.eqHex(t, "genesis_validator_hash", genDoc.ValidatorHash())
	v.eqHex(t, "bls_valset_hash", genDoc.ValidatorHash())
	require.Len(t, genDoc.Validators, numVals)
	for i, gv := range genDoc.Validators {
		assert.True(t, f.blsVals[i].PubKey.Equals(gv.PubKey), "genesis validator %d pubkey", i)
		assert.Equal(t, f.blsVals[i].Address, gv.Address)
		assert.Equal(t, f.blsVals[i].VotingPower, gv.Power)
	}
	// and it re-serializes to the same document apart from the extra
	// "authority" consensus param object this fork carries
	tmp := t.TempDir()
	require.NoError(t, genDoc.SaveAs(filepath.Join(tmp, "genesis.json")))
	reread, err := os.ReadFile(filepath.Join(tmp, "genesis.json"))
	require.NoError(t, err)
	var got, want map[string]json.RawMessage
	require.NoError(t, json.Unmarshal(reread, &got))
	require.NoError(t, json.Unmarshal([]byte(v.str(t, "genesis_json")), &want))
	for k := range want {
		if k == "consensus_params" {
			continue // checked above (modulo "authority")
		}
		assert.JSONEqf(t, string(want[k]), string(got[k]), "genesis.%s differs", k)
	}

	// priv_validator_key.json / priv_validator_state.json written by bera-v1.x
	keyFile := filepath.Join(tmp, "priv_validator_key.json")
	stateFile := filepath.Join(tmp, "priv_validator_state.json")
	require.NoError(t, os.WriteFile(keyFile, []byte(v.str(t, "priv_validator_key_json")), 0o600))
	require.NoError(t, os.WriteFile(stateFile, []byte(v.str(t, "priv_validator_state_json")), 0o600))
	pv := privval.LoadFilePV(keyFile, stateFile)
	pub, err := pv.GetPubKey()
	require.NoError(t, err)
	v.eqHex(t, "privval_pubkey", pub.Bytes())
	assert.True(t, f.blsVals[0].PubKey.Equals(pub))
	pvProp := types.NewProposal(height, round, -1, f.blockID, fixedTime).ToProto()
	require.NoError(t, pv.SignProposal(chainID, pvProp))
	v.eqHex(t, "privval_signed_proposal_signature", pvProp.Signature)
	pvVote := f.vote(cmtproto.PrecommitType, f.blockID, 0, f.blsVals[0].Address).ToProto()
	require.NoError(t, pv.SignVote(chainID, pvVote))
	v.eqHex(t, "privval_signed_vote_signature", pvVote.Signature)
	// FilePV on this fork always signs the (empty) vote extension of a non-nil
	// precommit; bera-v1.x's FilePV was asked not to. Consensus strips the
	// extension signature when vote extensions are disabled (see
	// types.SignAndCheckVote), so the vote that reaches the wire is identical.
	require.NotEmpty(t, pvVote.ExtensionSignature)
	pvVote.ExtensionSignature = nil
	v.eqHex(t, "privval_signed_vote_proto", mustMarshal(t, pvVote))
	// the last-signed state file matches bera-v1.x's (same height/round/step,
	// signature and sign bytes)
	stateAfter, err := os.ReadFile(stateFile)
	require.NoError(t, err)
	assert.JSONEq(t, v.str(t, "priv_validator_state_json_after_signing"), string(stateAfter))
	// a key file written by this fork is byte-identical to the bera-v1.x one
	pv2 := privval.NewFilePV(f.blsPrivs[0], filepath.Join(tmp, "k2.json"), filepath.Join(tmp, "s2.json"))
	pv2.Save()
	k2, err := os.ReadFile(filepath.Join(tmp, "k2.json"))
	require.NoError(t, err)
	assert.JSONEq(t, v.str(t, "priv_validator_key_json"), string(k2))
	s2, err := os.ReadFile(filepath.Join(tmp, "s2.json"))
	require.NoError(t, err)
	assert.JSONEq(t, v.str(t, "priv_validator_state_json"), string(s2))
	bz, err := cmtjson.Marshal(f.blsPrivs[0])
	require.NoError(t, err)
	assert.JSONEq(t, v.str(t, "bls_privkey0_cmtjson"), string(bz))
	v.eqHex(t, "bls_privkey0_bytes", f.blsPrivs[0].Bytes())
	pvEd := privval.NewFilePV(f.edPriv, filepath.Join(tmp, "ed.json"), filepath.Join(tmp, "ed_state.json"))
	pvEd.Save()
	ed, err := os.ReadFile(filepath.Join(tmp, "ed.json"))
	require.NoError(t, err)
	assert.JSONEq(t, v.str(t, "priv_validator_key_ed25519_json"), string(ed))
}

// TestWriteV040Outputs writes this fork's values for the shared inputs (same
// schema as vectors/bera_v1x_vectors.json, plus a few fork-specific extras) to
// the path in BERA_COMPAT_WRITE_OUTPUTS, for the reverse check performed by
// "gen-v1x -verify" (bera-v1.x decoding what this fork produces). It is a
// no-op unless the variable is set. See README.md.
func TestWriteV040Outputs(t *testing.T) {
	path := os.Getenv("BERA_COMPAT_WRITE_OUTPUTS")
	if path == "" {
		t.Skip("BERA_COMPAT_WRITE_OUTPUTS not set")
	}
	f := newFixture(t)
	out := map[string]any{}
	hx := hex.EncodeToString

	agg := f.aggCommit(t)
	out["agg_commit_proto"] = hx(mustMarshal(t, agg.ToProto()))
	out["agg_commit_hash"] = hx(agg.Hash())
	block, ps := f.block(t, agg)
	bp, err := block.ToProto()
	require.NoError(t, err)
	out["block_proto"] = hx(mustMarshal(t, bp))
	out["block_hash"] = hx(block.Hash())
	out["header_hash"] = hx(block.Header.Hash())
	out["block_partset_hash"] = hx(ps.Hash())
	out["block_meta_proto"] = hx(mustMarshal(t, types.NewBlockMeta(block, ps).ToProto()))
	precommit := f.signedBLSVote(t, f.blockID, 0)
	out["vote_proto_signed_precommit"] = hx(mustMarshal(t, precommit.ToProto()))
	out["vote_sign_bytes_precommit"] = hx(types.VoteSignBytes(chainID, precommit.ToProto()))
	proposal := types.NewProposal(height, round, 1, f.blockID, fixedTime)
	psig, err := f.blsPrivs[1].Sign(types.ProposalSignBytes(chainID, proposal.ToProto()))
	require.NoError(t, err)
	proposal.Signature = psig
	out["proposal_proto_signed"] = hx(mustMarshal(t, proposal.ToProto()))
	out["proposal_sign_bytes"] = hx(types.ProposalSignBytes(chainID, proposal.ToProto()))
	pp := f.params.ToProto()
	out["params_proto"] = hx(mustMarshal(t, &pp))
	out["params_hash"] = hx(f.params.Hash())
	bz, err := cmtjson.Marshal(f.params)
	require.NoError(t, err)
	out["params_json"] = string(bz)
	vsp, err := f.blsValSet.ToProto()
	require.NoError(t, err)
	out["bls_valset_proto"] = hx(mustMarshal(t, vsp))
	out["bls_valset_hash"] = hx(f.blsValSet.Hash())
	state := sm.State{
		Version:                          cmtstate.Version{Consensus: cmtversion.Consensus{Block: 11, App: 1}, Software: "1.0.1"},
		ChainID:                          chainID,
		InitialHeight:                    1,
		LastBlockHeight:                  height,
		LastBlockID:                      f.blockID,
		LastBlockTime:                    fixedTime,
		NextValidators:                   f.blsValSet.Copy(),
		Validators:                       f.blsValSet.Copy(),
		LastValidators:                   f.blsValSet.Copy(),
		LastHeightValidatorsChanged:      100,
		ConsensusParams:                  f.params,
		LastHeightConsensusParamsChanged: 50,
		LastResultsHash:                  h32("results"),
		AppHash:                          h32("app"),
		NextBlockDelay:                   1500 * time.Millisecond,
	}
	sp, err := state.ToProto()
	require.NoError(t, err)
	out["state_proto"] = hx(mustMarshal(t, sp))
	for name, m := range f.p2pMessages(t) {
		out[name] = hx(mustMarshal(t, m))
	}
	walVote := &cmtcons.TimedWALMessage{
		Time: fixedTime,
		Msg:  &cmtcons.WALMessage{Sum: &cmtcons.WALMessage_MsgInfo{MsgInfo: &cmtcons.MsgInfo{Msg: *f.p2pMessages(t)["p2p_vote"], PeerID: ""}}},
	}
	out["wal_msginfo_vote_proto"] = hx(mustMarshal(t, walVote))
	rt := fixedTimeNext
	walProposalRT := &cmtcons.TimedWALMessage{
		Time: fixedTime,
		Msg: &cmtcons.WALMessage{Sum: &cmtcons.WALMessage_MsgInfo{MsgInfo: &cmtcons.MsgInfo{
			Msg: *f.p2pMessages(t)["p2p_proposal"], PeerID: "peer1", ReceiveTime: &rt,
		}}},
	}
	out["wal_msginfo_proposal_with_receive_time_proto"] = hx(mustMarshal(t, walProposalRT))
	voteA := f.signedBLSVote(t, f.blockID, 2)
	otherBlockID := types.BlockID{Hash: h32("other-block"), PartSetHeader: types.PartSetHeader{Total: 3, Hash: h32("other-parts")}}
	voteB := f.signedBLSVote(t, otherBlockID, 2)
	dve, err := types.NewDuplicateVoteEvidence(voteA, voteB, fixedTime, f.blsValSet)
	require.NoError(t, err)
	evp, err := types.EvidenceToProto(dve)
	require.NoError(t, err)
	out["dve_proto"] = hx(mustMarshal(t, evp))
	out["dve_hash"] = hx(dve.Hash())

	// Fork-specific extras, for bera-v1.x to decode:
	// the FinalizeBlock response exactly as this fork persists it (pub_key set
	// by the app, pub_key_bytes/pub_key_type added on save) ...
	fbr := &abci.ResponseFinalizeBlock{
		ValidatorUpdates:      []abci.ValidatorUpdate{types.TM2PB.NewValidatorUpdate(f.blsVals[0].PubKey, 77)},
		ConsensusParamUpdates: paramsUpdate(),
		AppHash:               h32("app-next"),
		NextBlockDelay:        1500 * time.Millisecond,
	}
	fbr.ValidatorUpdates = types.NormalizeValidatorUpdates(fbr.ValidatorUpdates)
	out["v040_finalize_block_response_proto"] = hx(mustMarshal(t, fbr))
	out["v040_abci_responses_info_proto"] = hx(mustMarshal(t, &cmtstate.ABCIResponsesInfo{ResponseFinalizeBlock: fbr, Height: height}))
	// ... a genesis file written by this fork (carries the extra "authority" object) ...
	genDoc := types.GenesisDoc{
		GenesisTime:     fixedTime,
		ChainID:         chainID,
		InitialHeight:   1,
		ConsensusParams: &f.params,
		AppHash:         h32("genesis-app"),
		AppState:        json.RawMessage(`{"k":"v"}`),
	}
	for i := 0; i < numVals; i++ {
		genDoc.Validators = append(genDoc.Validators, types.GenesisValidator{
			Address: f.blsVals[i].Address, PubKey: f.blsVals[i].PubKey, Power: f.blsVals[i].VotingPower, Name: fmt.Sprintf("val%d", i),
		})
	}
	require.NoError(t, genDoc.ValidateAndComplete())
	tmp := t.TempDir()
	require.NoError(t, genDoc.SaveAs(filepath.Join(tmp, "genesis.json")))
	gj, err := os.ReadFile(filepath.Join(tmp, "genesis.json"))
	require.NoError(t, err)
	out["v040_genesis_json"] = string(gj)
	out["genesis_validator_hash"] = hx(genDoc.ValidatorHash())
	// ... and the key/state files written by this fork.
	pv := privval.NewFilePV(f.blsPrivs[0], filepath.Join(tmp, "k.json"), filepath.Join(tmp, "s.json"))
	pv.Save()
	kj, err := os.ReadFile(filepath.Join(tmp, "k.json"))
	require.NoError(t, err)
	out["v040_priv_validator_key_json"] = string(kj)
	sj, err := os.ReadFile(filepath.Join(tmp, "s.json"))
	require.NoError(t, err)
	out["v040_priv_validator_state_json"] = string(sj)

	out["_source"] = "generated by test/compat TestWriteV040Outputs against bera-v0.40.x"
	bz, err = json.MarshalIndent(out, "", "  ")
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(path, append(bz, '\n'), 0o644))
	t.Logf("wrote %s", path)
}

func TestVectorsBLSAggregation(t *testing.T) {
	v := loadVectors(t)
	f := newFixture(t)
	msg := []byte(v.str(t, "bls_aggregate_message"))
	sigs := make([][]byte, numVals)
	pubs := make([]*bls12381.PubKey, numVals)
	for i := 0; i < numVals; i++ {
		sig, err := f.blsPrivs[i].Sign(msg)
		require.NoError(t, err)
		sigs[i] = sig
		pubs[i] = blsPubPtr(f.blsPrivs[i].PubKey())
	}
	agg, err := bls12381.AggregateSignatures(sigs)
	require.NoError(t, err)
	v.eqHex(t, "bls_aggregate_signature", agg)
	assert.True(t, bls12381.VerifyAggregateSignature(agg, pubs, msg))
	assert.True(t, bls12381.VerifyAggregateSignature(v.hex(t, "bls_aggregate_signature"), pubs, msg))
}
